    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        // TODO add your handling code here:
        try
        {
            File vf=new File(path);   
            if(Desktop.isDesktopSupported())
                {
                    Desktop.getDesktop().open(vf);
                    
                }
                else 
                {
                    Runtime rt=Runtime.getRuntime();
                    rt.exec("cmd.exe /c start"+vf.getAbsolutePath());
                }
        }
        catch(Exception e)
        {
            JOptionPane.showMessageDialog(null,"Please First upload file");
        }
    }//GEN-LAST:event_jButton1ActionPerformed

    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        // TODO add your handling code here:
        JFileChooser fileChooser=new JFileChooser();
        fileChooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Video","mp4"));
        int response = fileChooser.showOpenDialog(this);
        if(response == JFileChooser.APPROVE_OPTION)
        {
            File selectedFile = fileChooser.getSelectedFile();
            path=""+selectedFile.getAbsolutePath();
        }   
        else
        {
            JOptionPane.showMessageDialog(null,"File opening operation cancelled by user.");
        }
    }//GEN-LAST:event_jButton2ActionPerformed

